<template><div class="biz-page todo-page" :class="'biz-size-'+appSize"><biz-page-header title="待办中心" description="统一处理责任、完成条件和时限升级" /><section class="todo-metrics"><todo-summary-card :value="dashboard.mine" label="我的待办" hint="当前需要处理" icon="el-icon-user" /><todo-summary-card :value="dashboard.candidate" label="候选池" hint="可以领取的工作" icon="el-icon-collection" /><todo-summary-card :value="dashboard.overdue" label="超时待办" hint="需要优先处理" icon="el-icon-alarm-clock" /></section><biz-table-card :show-search.sync="showSearch" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @query="search" @pagination="load"><template slot="filters"><div class="biz-filter-main"><el-radio-group v-model="query.mode" :size="controlSize" @change="search"><el-radio-button label="mine">我的</el-radio-button><el-radio-button label="candidate">候选池</el-radio-button><el-radio-button label="overdue">超时</el-radio-button></el-radio-group><el-input v-model="query.keyword" :size="controlSize" clearable placeholder="搜索标题或业务编号" prefix-icon="el-icon-search" @keyup.enter.native="search" /><el-select v-model="query.status" :size="controlSize" clearable placeholder="状态" @change="search"><el-option v-for="s in dict.type.law_todo_status" :key="s.value" :label="s.label" :value="s.value" /></el-select></div></template><el-table v-loading="loading" :data="rows"><el-table-column label="待办编号" prop="todo_no" width="160" /><el-table-column label="标题" min-width="200"><template slot-scope="{row}"><button class="todo-link" type="button" @click="openDetail(row)">{{ row.title }}</button><small>{{ row.business_no || '-' }}</small></template></el-table-column><el-table-column label="状态" width="120" align="center"><template slot-scope="{row}"><dict-tag :options="dict.type.law_todo_status" :value="row.status" /></template></el-table-column><el-table-column label="优先级" width="100" align="center"><template slot-scope="{row}"><dict-tag :options="dict.type.law_todo_priority" :value="row.priority" /></template></el-table-column><el-table-column label="SLA" width="110" align="center"><template slot-scope="{row}"><dict-tag :options="dict.type.law_todo_sla_status" :value="row.sla_status" /></template></el-table-column><el-table-column label="截止时间" prop="due_at" width="170" /><el-table-column label="操作" width="310" fixed="right" align="center"><template slot-scope="{row}"><el-button v-if="row.status==='CREATED'" v-hasPermi="['todo:claim']" type="text" @click="openAction(row,'claim')">领取</el-button><el-button v-if="['CLAIMED','RETURNED'].includes(row.status)" v-hasPermi="['todo:start']" type="text" @click="openAction(row,'start')">开始</el-button><el-button v-if="row.status==='IN_PROGRESS'" v-hasPermi="['todo:submit']" type="text" @click="openAction(row,'submit')">提交</el-button><el-button v-if="row.status==='SUBMITTED'" v-hasPermi="['todo:complete']" type="text" @click="openAction(row,'complete')">完成</el-button><el-button v-if="row.status==='SUBMITTED'" v-hasPermi="['todo:return']" type="text" @click="openAction(row,'return')">退回</el-button><el-button v-hasPermi="['todo:transfer']" type="text" @click="openAction(row,'transfer')">转派</el-button></template></el-table-column></el-table></biz-table-card><todo-detail-drawer :visible.sync="detailOpen" :detail="detail" /><todo-action-dialogs :visible.sync="actionOpen" :action="action" :submitting="submitting" @submit="execute" /></div></template>
<script>import businessUi from '@/views/business/mixins/businessUi';import BizPageHeader from '@/views/business/components/BizPageHeader';import BizTableCard from '@/views/business/components/BizTableCard';import TodoSummaryCard from './components/TodoSummaryCard';import TodoDetailDrawer from './components/TodoDetailDrawer';import TodoActionDialogs from './components/TodoActionDialogs';import {getTodoDashboard,listTodo,getTodo,claimTodo,startTodo,submitTodo,completeTodo,returnTodo,transferTodo,cancelTodo,addTodoAttachment} from '@/api/todo';const actions={claim:claimTodo,start:startTodo,submit:submitTodo,complete:completeTodo,return:returnTodo,transfer:transferTodo,cancel:cancelTodo};export default{name:'TodoCenter',dicts:['law_todo_status','law_todo_priority','law_todo_sla_status'],mixins:[businessUi],components:{BizPageHeader,BizTableCard,TodoSummaryCard,TodoDetailDrawer,TodoActionDialogs},data(){return{showSearch:true,loading:false,submitting:false,total:0,rows:[],dashboard:{mine:0,candidate:0,overdue:0},query:{pageNum:1,pageSize:10,mode:'mine',keyword:'',status:''},statuses:['CREATED','CLAIMED','IN_PROGRESS','SUBMITTED','RETURNED','COMPLETED','CANCELLED'],detailOpen:false,detail:{},actionOpen:false,action:'',selected:null}},created(){this.refresh()},methods:{refresh(){getTodoDashboard().then(r=>{this.dashboard=r.data||{}});this.load()},load(){this.loading=true;listTodo(this.query).then(r=>{this.rows=r.rows||[];this.total=r.total||0}).finally(()=>{this.loading=false})},search(){this.query.pageNum=1;this.load()},openDetail(row){getTodo(row.todo_id).then(r=>{this.detail=r.data||{};this.detailOpen=true})},openAction(row,action){this.selected=row;this.action=action;this.actionOpen=true},execute(form){this.submitting=true;const data={actionId:`web-${Date.now()}-${Math.random().toString(16).slice(2)}`,opinion:form.opinion,payload:form.payload};const upload=form.fileUrl&&this.action==='complete'?addTodoAttachment(this.selected.todo_id,{actionId:data.actionId,attachmentType:'CONTACT_PROOF',fileName:form.fileUrl.split('/').pop(),fileUrl:form.fileUrl}):Promise.resolve();upload.then(()=>actions[this.action](this.selected.todo_id,data)).then(()=>{this.$modal.msgSuccess('处理成功');this.actionOpen=false;this.refresh()}).finally(()=>{this.submitting=false})}}}</script>
<style scoped lang="scss">@import "../business/business.scss";.todo-page{--biz-filter-input-width:260px}.todo-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:14px 0}.todo-link{display:block;padding:0;border:0;background:none;color:#1d4ed8;cursor:pointer}.todo-link:focus{outline:2px solid #2563eb;outline-offset:2px}.todo-link+small{display:block;color:#64748b}@media(max-width:768px){.todo-metrics{grid-template-columns:1fr}}</style>
